CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('ADMIN','TEACHER','STUDENT');
CREATE TYPE account_status AS ENUM ('ACTIVE','INACTIVE','SUSPENDED');
CREATE TYPE assignment_status AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
CREATE TYPE attempt_status AS ENUM ('IN_PROGRESS','SUBMITTED','PENDING_GRADING','GRADED');

CREATE TABLE tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), email text NOT NULL, password_hash text NOT NULL, name text NOT NULL, role user_role NOT NULL, status account_status NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz, UNIQUE(tenant_id,email));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE programs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), slug text NOT NULL, title text NOT NULL, summary text NOT NULL, audience text NOT NULL, outcomes text NOT NULL, is_published boolean NOT NULL DEFAULT false, UNIQUE(tenant_id,slug));
CREATE TABLE classes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), program_id uuid REFERENCES programs(id), teacher_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, level text NOT NULL, modality text NOT NULL, location text, starts_on date NOT NULL, ends_on date, recruiting boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), class_id uuid NOT NULL REFERENCES classes(id), student_id uuid NOT NULL REFERENCES users(id), status text NOT NULL DEFAULT 'ACTIVE', enrolled_at timestamptz NOT NULL DEFAULT now(), UNIQUE(class_id,student_id));
CREATE TABLE class_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), class_id uuid NOT NULL REFERENCES classes(id), weekday smallint NOT NULL CHECK (weekday BETWEEN 0 AND 6), starts_at time NOT NULL, ends_at time NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Ho_Chi_Minh');
CREATE TABLE resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), title text NOT NULL, description text NOT NULL DEFAULT '', mime_type text NOT NULL, object_key text, is_downloadable boolean NOT NULL DEFAULT true, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE resource_class_access (resource_id uuid NOT NULL REFERENCES resources(id) ON DELETE CASCADE, class_id uuid NOT NULL REFERENCES classes(id) ON DELETE CASCADE, PRIMARY KEY(resource_id,class_id));
CREATE TABLE assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), class_id uuid NOT NULL REFERENCES classes(id), created_by uuid NOT NULL REFERENCES users(id), title text NOT NULL, instructions text NOT NULL, due_at timestamptz, status assignment_status NOT NULL DEFAULT 'DRAFT', max_attempts integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE questions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id uuid NOT NULL REFERENCES assignments(id) ON DELETE CASCADE, type text NOT NULL CHECK (type IN ('SINGLE_CHOICE','TRUE_FALSE','SHORT_ANSWER')), prompt text NOT NULL, options jsonb, correct_answer jsonb, points numeric(7,2) NOT NULL DEFAULT 1, position integer NOT NULL);
CREATE TABLE attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id uuid NOT NULL REFERENCES assignments(id), student_id uuid NOT NULL REFERENCES users(id), attempt_no integer NOT NULL DEFAULT 1, status attempt_status NOT NULL DEFAULT 'IN_PROGRESS', answers jsonb NOT NULL DEFAULT '{}', score numeric(7,2), started_at timestamptz NOT NULL DEFAULT now(), saved_at timestamptz NOT NULL DEFAULT now(), submitted_at timestamptz, graded_at timestamptz, teacher_feedback text, UNIQUE(assignment_id,student_id,attempt_no));
CREATE TABLE enrollment_inquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), full_name text NOT NULL, phone text NOT NULL, email text, program_id uuid REFERENCES programs(id), current_level text NOT NULL, note text, status text NOT NULL DEFAULT 'NEW', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id bigserial PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES tenants(id), actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_enrollments_student ON enrollments(student_id,status);
CREATE INDEX idx_assignments_class_status ON assignments(class_id,status);
CREATE INDEX idx_attempts_student ON attempts(student_id,status);
CREATE INDEX idx_inquiries_status_created ON enrollment_inquiries(status,created_at DESC);
